import base64,hashlib,json,os,pathlib,platform,subprocess,sys
ROOT=pathlib.Path.cwd()
OUT=ROOT/'.cache/cap-checkpoint-review-ci';OUT.mkdir(parents=True,exist_ok=True)
CONFIG={'cap_patch': '', 'checkpoint_method': '', 'feature_head': '444574996e66bc6792fce647a6bdba8fb456ffd6', 'prior_session_protocol': ''}
CI_FILES={'.github/workflows/sync-cap-checkpoint-review.yml','scripts/inspect-sync-cap-checkpoint-review.py'}
def sha(b):return hashlib.sha256(b).hexdigest()
def manifest():
 names=subprocess.check_output(['git','ls-files','-z']).decode().split('\0')
 return {n:sha((ROOT/n).read_bytes()) for n in sorted(names) if n and n not in CI_FILES}
SOURCE=manifest()
(OUT/'source-manifest.json').write_text(json.dumps(SOURCE,sort_keys=True,indent=2)+'\n')
receipt={'feature_head':CONFIG['feature_head'],'ci_head':subprocess.check_output(['git','rev-parse','HEAD']).decode().strip(),'platform':platform.system(),'architecture':platform.machine(),'go':subprocess.check_output(['go','version']).decode().strip(),'source_manifest_sha256':sha(json.dumps(SOURCE,sort_keys=True,separators=(',',':')).encode()),'commands':[]}
def check_source():
 if manifest()!=SOURCE:raise RuntimeError('tracked source changed during native command')
def overlay(name,changes):
 target=OUT/name;target.mkdir(exist_ok=True)
 mapping={}
 for n,raw in changes.items():
  p=target/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(raw)
  mapping[str(ROOT/n)]=str(p)
 p=OUT/(name+'-overlay.json');p.write_text(json.dumps({'Replace':mapping},sort_keys=True))
 return str(p)
def run(name,args,expected=(),failure=False):
 check_source();log=OUT/(name+'.jsonl')
 with log.open('wb') as f:code=subprocess.run(args,stdout=f,stderr=subprocess.STDOUT).returncode
 check_source()
 raw=log.read_bytes();events=[]
 for line in raw.splitlines():
  try:events.append(json.loads(line))
  except ValueError:pass
 passed=[e['Test'] for e in events if e.get('Action')=='pass' and e.get('Test')]
 failed=[e['Test'] for e in events if e.get('Action')=='fail' and e.get('Test')]
 skipped=[e['Test'] for e in events if e.get('Action')=='skip' and e.get('Test')]
 result={'name':name,'argv':args,'exit':code,'log_sha256':sha(raw),'passed':passed,'failed':failed,'skipped':skipped,'source_unchanged':True}
 # Normalize tool paths in the technical receipt; raw logs stay in CI artifacts.
 result['argv']=[a.replace(str(ROOT),'<checkout>') for a in args]
 receipt['commands'].append(result)
 (OUT/'receipt.json').write_text(json.dumps(receipt,sort_keys=True,indent=2)+'\n')
 if failure:
  if code==0 or not set(expected)<=set(failed):raise RuntimeError(name+' failed to reproduce exact expected original failures')
 else:
  if code!=0 or failed or skipped:raise RuntimeError(name+' native gate failed or skipped')
  if not set(expected)<=set(passed):raise RuntimeError(name+' missing required actual cases')
 print(name+': exit='+str(code)+' pass='+str(len(passed))+' fail='+str(len(failed))+' skip='+str(len(skipped)),flush=True)
common=['go','test','-mod=readonly','-p=1','-race','-json','-count=1','-timeout=3m']
old=base64.b64decode(CONFIG['prior_session_protocol']).decode()
prior=overlay('original-session',{'internal/syncworker/protocol.go':old})
run('original-session',common+['-overlay',prior,'./internal/syncworker','-run','^TestWorkerAllocationCheckpointRetainsEvidenceAcrossPublicationCuts$/^after-session-replacement$'],expected=['TestWorkerAllocationCheckpointRetainsEvidenceAcrossPublicationCuts','TestWorkerAllocationCheckpointRetainsEvidenceAcrossPublicationCuts/after-session-replacement'],failure=True)
if 'original cleanup joined' not in (OUT/'original-session.jsonl').read_text():raise RuntimeError('original session counterexample cleanup witness missing')
run('final-worker',common+['./internal/syncworker','-run','^(TestStagingCapReview|TestWorkerAllocationCheckpoint|TestFixed|TestFailedTransportJoin|TestConflict|TestCancellationClosesBlocked|TestUnreviewed|TestWorkspaceReview|TestDestinationBridge|TestControlRejects)'],expected=['TestFixedSyncWorkerOverARMSSHSession','TestStagingCapReviewActualSSHAbortUnblocksStalledWriterAndJoins','TestWorkerAllocationCheckpointRetainsEvidenceAcrossPublicationCuts/after-session-replacement'])
run('final-worker-vet',['go','vet','-mod=readonly','-p=1','./internal/syncworker'])
check_source();receipt['complete']=True
(OUT/'receipt.json').write_text(json.dumps(receipt,sort_keys=True,indent=2)+'\n')
